def rand(*args)
  Kernel.rand(*args)
end

class << Kernel
  alias oldRand rand unless method_defined?(:oldRand)
  def rand(a = nil, b = nil)
    if a.is_a?(Range)
      lo = a.min
      hi = a.max
      return lo + oldRand(hi - lo + 1)
    elsif a.is_a?(Numeric)
      if b.is_a?(Numeric)
        return a + oldRand(b - a + 1)
      else
        return oldRand(a)
      end
    elsif a.nil?
      return oldRand(b)
    end
    return oldRand
  end
end

def pbRun(idxBattler, duringBattle = false)
  ret = super
  @rounds[@roundindex][idxBattler] = [Commands::RUN, @decision]
  return ret
end

def pbRandom(num)
  ret = super(num)
  @randomnumbers.push(ret)
  return ret
end

def pbRandom(_num)
  ret = @randomnums[@randomindex]
  @randomindex += 1
  return ret
end
